  if (tid == 0) {
    __threadfence();
    const unsigned old = atomicAdd(p.ctr + CT_DEP, 1u);
    if (old == gridDim.x - 1) {
      __threadfence();
      p.ctr[CT_HEAD] = 0u;
      p.ctr[CT_W1] = 0u;
      p.ctr[CT_W2] = 0u;
