// ---------------------------------------------------------------- host
struct HArgs {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *b1, *gw, *gb, *w2, *b2;
  float* out;
  int B, C, H, W;
  float eps, ln_eps;
  void* stamps;
};

static inline size_t al256(size_t v) { return (v + 255) & ~(size_t)255; }
struct WsLayout { size_t w1h, w2h, u1, c1, gsum, part, d16, h16, g16, total; };
static WsLayout ws_layout(int B, int C, int W) {
  const size_t HWP = (W == 7) ? 64 : 256, LDT = (size_t)B * HWP, C4 = 4 * (size_t)C;
  WsLayout L;
  size_t o = 0;
  L.w1h = o; o = al256(o + C4 * C * 2);
  L.w2h = o; o = al256(o + C4 * C * 2);
  L.u1 = o; o = al256(o + C4 * 4);
  L.c1 = o; o = al256(o + C4 * 4);
  L.gsum = o; o = al256(o + 64 * 4);
  L.part = o; o = al256(o + (size_t)B * (C / 32) * 2 * HWP * 4);
  L.d16 = o; o = al256(o + (size_t)C * LDT * 2);
  L.h16 = o; o = al256(o + C4 * LDT * 2);
  L.g16 = o; o = al256(o + C4 * LDT * 2);
  L.total = o;
  return L;
}

extern "C" size_t h_ws_bytes(int B, int C, int H, int W) { (void)H; return ws_layout(B, C, W).total; }

static bool enc2d(CUtensorMap* m, const void* ptr, uint64_t inner, uint64_t outer, uint32_t box_in, uint32_t box_out) {
  cuuint64_t dims[2] = {(cuuint64_t)inner, (cuuint64_t)outer};
  cuuint64_t strides[1] = {(cuuint64_t)(inner * 2)};
  cuuint32_t box[2] = {box_in, box_out};
  cuuint32_t es[2] = {1, 1};
  return cuTensorMapEncodeTiled(m, CU_TENSOR_MAP_DATA_TYPE_FLOAT16, 2, const_cast<void*>(ptr), dims, strides, box, es,
                                CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B,
                                CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) == CUDA_SUCCESS;
}

extern "C" const char* h_launch(const HArgs* a, void* ws, void* stream) {
  using namespace hk;
  static int sms = 0;
  static unsigned* ctr = nullptr;
  cudaError_t e;
  if (sms == 0) {
    int dev = 0;
    cudaGetDevice(&dev);
    cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
    e = cudaFuncSetAttribute(h_kernel<768, 7>, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_TOTAL);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    e = cudaFuncSetAttribute(h_kernel<384, 14>, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_TOTAL);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    void* cp = nullptr;
    e = cudaGetSymbolAddress(&cp, g_hctr);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    ctr = (unsigned*)cp;
  }
  const int B = a->B, C = a->C, W = a->W, C4 = 4 * C;
  const int HWP = (W == 7) ? 64 : 256, LDT = B * HWP;
  const WsLayout L = ws_layout(B, C, W);
  char* w = (char*)ws;
  HP hp;
  memset(&hp, 0, sizeof(hp));
  hp.x = a->x; hp.dww = a->dww; hp.dwb = a->dwb; hp.lnw = a->lnw; hp.lnb = a->lnb; hp.w1 = a->w1; hp.b1 = a->b1;
  hp.gw = a->gw; hp.gb = a->gb; hp.w2 = a->w2; hp.b2 = a->b2; hp.out = a->out;
  hp.w1h = (__half*)(w + L.w1h); hp.w2h = (__half*)(w + L.w2h);
  hp.u1 = (float*)(w + L.u1); hp.c1 = (float*)(w + L.c1); hp.gsum = (float*)(w + L.gsum);
  hp.part = (float*)(w + L.part); hp.d16 = (__half*)(w + L.d16); hp.h16 = (__half*)(w + L.h16);
  hp.g16 = (__half*)(w + L.g16);
  hp.ctr = ctr;
  hp.stamps = (unsigned long long*)a->stamps;
  if (!enc2d(&hp.tmW1, hp.w1h, C, C4, 64, 128)) return "tmW1 encode";
  if (!enc2d(&hp.tmW2, hp.w2h, C4, C, 64, 128)) return "tmW2 encode";
  if (!enc2d(&hp.tmD, hp.d16, LDT, C, 64, 64)) return "tmD encode";
  if (!enc2d(&hp.tmH, hp.h16, LDT, C4, 64, 64)) return "tmH encode";
  if (!enc2d(&hp.tmG, hp.g16, LDT, C4, 64, 64)) return "tmG encode";
  hp.B = B; hp.LDT = LDT; hp.nW = sms;
  hp.eps = a->eps; hp.ln_eps = a->ln_eps;
  int IPT2;
  if (C == 768) {
    hp.PG = (B <= 8) ? 32 : (B <= 16 ? 64 : 128);
    hp.IPT1 = 2; hp.N1 = 128; hp.NCH1 = 2; hp.NTS = 1; hp.KS2 = 4; IPT2 = 2;
  } else {
    hp.PG = 32;
    hp.IPT1 = 1; hp.N1 = 208; hp.NCH1 = 4; hp.NTS = 2; hp.KS2 = 2; IPT2 = 1;
  }
  hp.NG = C / hp.PG;
  const int MT1 = C4 / 128, MT2 = C / 128;
  const int nConv = B * hp.NG, nG1 = (B / hp.IPT1) * MT1, nG2 = (B / IPT2) * hp.NTS * MT2 * hp.KS2;
  hp.o_conv = hp.nW;
  hp.o_w2 = hp.o_conv + nConv;
  hp.o_g1 = hp.o_w2 + hp.nW;
  hp.o_g2 = hp.o_g1 + nG1;
  hp.n_total = hp.o_g2 + nG2;
  void* args[] = {&hp};
  const void* fn = (C == 768) ? (const void*)h_kernel<768, 7> : (const void*)h_kernel<384, 14>;
  e = cudaLaunchCooperativeKernel(fn, dim3(sms), dim3(NTH), args, (size_t)SMEM_TOTAL, (cudaStream_t)stream);
  if (e != cudaSuccess) return cudaGetErrorString(e);
  return nullptr;
}
