empty=torch.empty(0,device='cuda'); flush=torch.empty(64*1024*1024, device='cuda')
def stamps(mod,B,C,H,W,inp):
    out=torch.zeros(B,C,H,W,device='cuda'); st=torch.zeros(4096*8, dtype=torch.int64, device='cuda')
