    s=s[:o[5]]; t0=s[:,0].min()
    for c in (0,1,2,4,5): s[:,c]=(s[:,c]-t0)/1000.0
    md=lambda v: f'{v.median():.2f}/{v.max():.2f}'
    names=['W1','conv','G1','W2','G2']; line=f'span {s[:,2].max():.1f} | '
    for k in range(5):
