    g1=s[o[2]:o[3]]; g2=s[o[4]:o[5]]
    line+=f'\n   G1 wait {md(g1[:,1]-g1[:,0])} main {md(g1[:,4]-g1[:,1])} p1 {md(g1[:,5]-g1[:,4])} rest {md(g1[:,2]-g1[:,5])} | G2 wait {md(g2[:,1]-g2[:,0])} main {md(g2[:,4]-g2[:,1])} epi {md(g2[:,2]-g2[:,4])}'
